INSERT INTO `courses` (`id`, `title`, `description`, `thumbnail`, `duration`, `difficulty`, `category`, `status`, `created_at`, `updated_at`) VALUES (5,'React JS: From Fundamentals to API Integration','Learn React JS from **fundamentals to API integration**. Build a strong foundation in JSX, Components, Props, State, Hooks, Routing, and API Calling through simple practical examples.',NULL,NULL,'Beginner','Web Development','published','2026-09-02 08:58:32','2026-09-02 08:58:49'),(6,'Java Programming: Build Your Core Skills','Learn Java programming from the basics to intermediate concepts. This course covers core Java fundamentals, OOP concepts, exception handling, file handling, and collections to help students build strong programming skills and develop practical Java applications.',NULL,NULL,'Intermediate','Java Programming','published','2026-09-02 19:09:31','2026-09-02 19:09:31'),(7,'JavaScript Mastery: From Basics to Advanced','JavaScript Mastery: From Basics to Advanced** is a complete JavaScript course covering core concepts, modern ES6+ features, DOM manipulation, asynchronous programming, APIs, and advanced JavaScript concepts. It helps students build strong fundamentals and develop practical skills for modern web development.',NULL,NULL,'Advanced','JavaScript Programming','published','2026-09-03 03:03:25','2026-09-03 03:55:51'),(8,'Python Programming','Python Programming: From Basics to Advanced is a complete Python course covering basic programming concepts, functions, data structures, OOP, file handling, APIs, databases, and advanced Python features. It helps students build strong programming fundamentals and develop practical Python skills.',NULL,NULL,'Advanced','Backend Development','published','2026-09-03 08:58:44','2026-09-03 08:58:44');
