INSERT INTO `quiz_questions` (`id`, `quiz_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `marks`, `created_at`, `updated_at`) VALUES (47,7,'What is React JS?','A database','A JavaScript library','A programming language','A web server','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(48,7,'What is the main purpose of React?','To manage databases','To build user interfaces','To create servers','To manage files','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(49,7,'Who developed React?','Google','Facebook','Microsoft','Amazon','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(50,7,'Which command creates a new Vite React project?','npm create vite','npm install react','npm start react','node create react','a',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(51,7,'Which file is commonly used as the entry point in a Vite React project?','index.html','main.jsx','package.json','style.css','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(52,7,'What does JSX stand for?','Java Syntax Extension','JavaScript XML','Java XML','JavaScript Extension','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(53,7,'Which syntax is used to write JavaScript inside JSX?','[]','{}','()','<>','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(54,7,'Can JSX return multiple elements?','No','Yes, using a parent element','Only with CSS','Only with HTML','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(55,7,'What is a React component?','A database table','A reusable UI part','A CSS property','A server','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(56,7,'Which naming convention is normally used for React components?','lowercase','uppercase','only numbers','symbols','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(57,7,'Which component syntax is valid in React?','function App() {}','component App() {}','react App() {}','create App() {}','a',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(58,7,'What are Props used for?','To store database data','To pass data between components','To create CSS','To install React','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(59,7,'Props are generally passed from which component to which component?','Child to parent','Parent to child','Server to browser','Browser to server','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(60,7,'Can Props be directly modified by a child component?','Yes','No','Only in Vite','Only with Axios','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(61,7,'Which Hook is used to manage state?','useEffect','useState','useRouter','useAPI','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(62,7,'What does useState return?','Only a value','A value and a setter function','A component','A route','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(63,7,'What happens when state changes?','The component can re-render','The browser closes','React is deleted','The server stops','a',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(64,7,'Which event is commonly used for a button click?','onChange','onClick','onSubmit','onLoad','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(65,7,'Which event is commonly used with input fields?','onClick','onChange','onRoute','onFetch','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(66,7,'Which event is used when a form is submitted?','onClick','onChange','onSubmit','onLoad','c',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(67,7,'Which Hook is used for side effects?','useState','useEffect','useProps','useEvent','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(68,7,'When does useEffect run with an empty dependency array?','After every render','After the initial render','Never','Before React starts','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(69,7,'Which library is commonly used for routing in React?','Axios','React Router','Express','MongoDB','b',1,'2026-09-02 09:39:00','2026-09-02 09:39:00'),(70,7,'Which component is used to define a route in React Router?','RouteLink','Route','RouterPage','LinkRoute'