INSERT INTO `projects` (`id`, `course_id`, `title`, `description`, `required_skills`, `difficulty`, `deadline`, `requirements`, `status`, `created_at`, `updated_at`) VALUES (5,5,'React JS Learning Management System','A React-based learning platform where students can explore courses, access lessons, take quizzes, and track their learning progress through a simple and interactive interface.','React','Intermediate','2026-10-30','React JS, Vite, JavaScript, HTML/CSS, React Router, Axios/Fetch API, Node.js, VS Code, and a modern web browser.','published','2026-09-02 09:42:30','2026-09-02 09:42:30'),(6,6,'JavaTech Hub','**JavaTech Hub** is a Java programming platform designed to provide structured courses, practical coding lessons, quizzes, and programming resources. It helps students build strong Java fundamentals and develop their programming skills through an organized and interactive experience.','Java, OOPS','Advanced','2026-10-28','Admin will provide students with Java course content including lessons, notes, videos, quizzes, and assignments. Admin can add, update, and manage course materials, create quiz questions, monitor student progress, and manage student submissions and course completion','published','2026-09-03 01:54:20','2026-09-03 01:54:20'),(7,7,'Weather Dashboard','**Weather Dashboard** is a JavaScript-based web application that allows users to check **current weather information and forecasts** for different cities. It uses a weather API to display temperature, humidity, wind speed, weather conditions, and other useful information in a simple and user-friendly dashboard.','Javascript, Html','Beginner','2026-10-06','**Requirement:** The project requires JavaScript, HTML, and CSS for frontend development, along with a weather API to fetch real-time weather data. Users should be able to search cities and view temperature, humidity, wind speed, weather conditions, and forecast information.','published','2026-09-03 03:58:24','2026-09-03 03:58:24'),(8,8,'Quiz Application','Python Learning Management System is an educational platform designed to help students learn Python programming through structured lessons, notes, quizzes, assignments, and practical learning resources.','Python, OOP, File Handling, Exception Handling, JSON, REST APIs, MySQL, SQL, HTML, CSS','Intermediate','2026-11-10','build a basic Quiz Application in Python, the core requirements include a structured data format (like dictionaries or lists of tuples) to securely store questions, multiple-choice options, and correct answers. The system must feature a user interaction mechanism via a text-based console interface (input() function) or a graphical interface like Tkinter to display prompts and capture choices.','published','2026-09-03 09:50:33','2026-09-03 09:50:33');
/*!40000 ALTER TABLE `projects` ENABLE KEYS */;
